def parsear_duracion(s):
    if not s:
        return 0
    partes = s.split()
    total = 0
    for parte in partes:
        if parte.endswith('h'):
            total += int(parte[:-1]) * 60
        elif parte.endswith('m'):
            total += int(parte[:-1])
    return total

def es_palindromo(s):
