def fusionar(intervalos):
    if not intervals:
        return []

    # Inicializar lista con el primer intervalo
    intervalo_actual = intervals[0]

    # Iterar sobre los intervalos restantes
    for inicio, fin in intervals[1:]:
        # Si el siguiente intervalo toca o se superpone con el actual
        if inicio <= intervalo_actual[1]:
            # Fusionar: actualizar el fin del intervalo actual
            intervalo_actual = (inicio, max(intervalo_actual[1], fin))
        else:
            # Si no hay superposición, agregar el intervalo actual a la lista
            intervalo_actual = (inicio, fin)

    return intervalo_actual

