    unidad = "B"
    valor = n

    if valor >= 1024:
        unidad = "KB"
        valor = valor / 1024
    elif valor >= 1024:
        unidad = "MB"
        valor = valor / 1024 / 1024
    elif valor >= 1024:
        unidad = "GB"
        valor = valor / 1024 / 1024 / 1024

